const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Are You Getting What You Pay For? Auditing Model Substitution in LLM APIs'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();

  // Left panel - deep navy background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 6.0, h: 5.625,
    fill: { color: theme.primary }
  });

  // Right panel - light background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.0, y: 0, w: 4.0, h: 5.625,
    fill: { color: theme.bg }
  });

  // Decorative geometric shapes on right side (abstract security/verification motif)
  const makeShadow = () => ({ type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.1 });

  // Large overlapping rectangles
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 0.5, w: 2.5, h: 2.0,
    fill: { color: theme.secondary, transparency: 30 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 1.2, w: 2.5, h: 2.0,
    fill: { color: theme.accent, transparency: 20 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 3.0, w: 2.8, h: 1.5,
    fill: { color: theme.light, transparency: 40 },
    shadow: makeShadow()
  });

  // Shield-like shape (triangle approximation using rectangles)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.8, y: 2.0, w: 1.5, h: 1.8,
    fill: { color: theme.accent, transparency: 15 },
    shadow: makeShadow()
  });

  // Horizontal accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.6, w: 1.5, h: 0.06,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("Are You Getting\nWhat You Pay For?", {
    x: 0.6, y: 1.8, w: 5.0, h: 1.6,
    fontSize: 40, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    margin: 0
  });

  // Subtitle line 1
  slide.addText("Auditing Model Substitution in LLM APIs", {
    x: 0.6, y: 3.5, w: 5.0, h: 0.5,
    fontSize: 20, fontFace: "Georgia",
    color: theme.accent, bold: false, align: "left",
    margin: 0
  });

  // Subtitle line 2
  slide.addText("Why Software Tests Fail and Hardware Attestation Wins", {
    x: 0.6, y: 4.0, w: 5.0, h: 0.4,
    fontSize: 15, fontFace: "Calibri",
    color: theme.light, bold: false, align: "left",
    margin: 0
  });

  // Source reference
  slide.addText("arxiv.org/abs/2504.04715", {
    x: 0.6, y: 4.6, w: 3.0, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.light, bold: false, align: "left",
    margin: 0
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

