const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'The Model Substitution Problem: Economic Incentives Drive Covert Swaps'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("The Model Substitution Problem", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.55,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("Economic Incentives Drive Covert Swaps", {
    x: 0.4, y: 0.75, w: 9.2, h: 0.3,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // 2x2 card grid
  const cards = [
    { title: "Smaller Model", desc: "8B served instead of 70B; dramatic cost reduction with obvious quality loss", accentColor: theme.accent },
    { title: "Quantized Variant", desc: "FP8/INT8 instead of FP16; minimal benchmark impact, hard to detect", accentColor: theme.secondary },
    { title: "Fine-Tuned Version", desc: "Modified weights or updated checkpoint; distribution shift undetectable without reference", accentColor: theme.accent },
    { title: "Different Family", desc: "Entirely different architecture; requires only output-level similarity", accentColor: theme.secondary }
  ];

  const cardW = 4.2, cardH = 1.35, gapX = 0.3, gapY = 0.2;
  const startX = 0.4, startY = 1.25;

  cards.forEach((card, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const cx = startX + col * (cardW + gapX);
    const cy = startY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      rectRadius: 0.03,
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
    });

    // Left accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: 0.06, h: cardH,
      fill: { color: card.accentColor }
    });

    // Small colored circle icon
    slide.addShape(pres.shapes.OVAL, {
      x: cx + 0.25, y: cy + 0.2, w: 0.35, h: 0.35,
      fill: { color: card.accentColor }
    });

    // Card number inside circle
    slide.addText(String(i + 1), {
      x: cx + 0.25, y: cy + 0.2, w: 0.35, h: 0.35,
      fontSize: 13, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    // Card title
    slide.addText(card.title, {
      x: cx + 0.7, y: cy + 0.15, w: cardW - 0.9, h: 0.35,
      fontSize: 14, fontFace: "Calibri",
      color: theme.primary, bold: true, align: "left", margin: 0
    });

    // Card description
    slide.addText(card.desc, {
      x: cx + 0.7, y: cy + 0.55, w: cardW - 0.9, h: 0.7,
      fontSize: 11, fontFace: "Calibri",
      color: theme.secondary, bold: false, align: "left", margin: 0, valign: "top"
    });
  });

  // Bottom section - hypothesis testing framework
  const hyY = 4.35;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: hyY, w: 9.2, h: 0.85,
    fill: { color: theme.primary },
    rectRadius: 0.03
  });

  slide.addText([
    { text: "H", options: { italic: true, fontSize: 13 } },
    { text: "₀", options: { fontSize: 10 } },
    { text: ": API serves P", options: { fontSize: 13 } },
    { text: "spec", options: { fontSize: 10, italic: true } },
    { text: "(y|x) — the specified model          ", options: { fontSize: 13 } },
    { text: "H", options: { italic: true, fontSize: 13 } },
    { text: "₁", options: { fontSize: 10 } },
    { text: ": API serves P", options: { fontSize: 13 } },
    { text: "actual", options: { fontSize: 10, italic: true } },
    { text: "(y|x) — an alternative model", options: { fontSize: 13 } },
  ], {
    x: 0.7, y: hyY + 0.05, w: 8.6, h: 0.4,
    fontFace: "Calibri", color: "FFFFFF", align: "left", valign: "middle"
  });

  slide.addText("Auditor must distinguish these distributions from output samples alone", {
    x: 0.7, y: hyY + 0.42, w: 8.6, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: theme.light, bold: false, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

