    sizing: { type: 'contain', w: 5.2, h: 3.4 }
  });

  // Right side - takeaway cards
  const takeaways = [
    { text: "Temperature scaling from 0.2 to 2.0 degrades performance across all five models and four tasks", accentColor: theme.accent },
