    const cy = cardStartY + i * (cardH + cardGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: cy, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      rectRadius: 0.03,
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
    });

    // Left accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: cy, w: 0.06, h: cardH,
      fill: { color: item.accentColor }
    });

    // Card text
    slide.addText(item.text, {
      x: cardX + 0.2, y: cy + 0.1, w: cardW - 0.35, h: cardH - 0.2,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Source caption under image
  slide.addText("Source: arxiv.org/abs/2504.04715, Figure 1", {
    x: 0.4, y: 4.5, w: 5.2, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

