const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Log Probability Fingerprinting Fails Due to Inference Nondeterminism'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Log Probability Fingerprinting Fails Due to Inference Nondeterminism", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0, fit: "shrink"
  });

  // Left side content - explanation
  slide.addText("Comparing token-level log probabilities between a local reference and the API seems promising — but production environments introduce significant nondeterminism.", {
    x: 0.4, y: 1.0, w: 4.3, h: 0.8,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0, valign: "top"
  });

  // Variation sources with colored markers
  const sources = [
    { label: "Software: transformers 4.40 vs 4.50", color: theme.accent },
    { label: "Software: vLLM 0.6.2 vs 0.8.2", color: theme.secondary },
    { label: "Hardware: A100 vs H100 GPUs", color: theme.accent }
  ];

  const srcStartY = 2.0;
  sources.forEach((src, i) => {
    const sy = srcStartY + i * 0.45;

    // Colored square marker
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: sy + 0.05, w: 0.18, h: 0.18,
      fill: { color: src.color }
    });

    slide.addText(src.label, {
      x: 0.8, y: sy, w: 3.8, h: 0.3,
      fontSize: 12, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Callout box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.5, w: 4.3, h: 0.85,
    fill: { color: theme.accent },
    rectRadius: 0.03
  });
  slide.addText("An auditor cannot distinguish legitimate infrastructure variation from actual model substitution.", {
    x: 0.6, y: 3.5, w: 3.9, h: 0.85,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "left", valign: "middle"
  });

  // Right side - image (REVERSED layout from slide 4)
  slide.addImage({
    path: "./imgs/figure_5.jpg",
    x: 5.0, y: 1.0, w: 4.6, h: 3.4,
    sizing: { type: 'contain', w: 4.6, h: 3.4 }
  });

  // Source caption under image
  slide.addText("Source: arxiv.org/abs/2504.04715, Figure 5", {
    x: 5.0, y: 4.5, w: 4.6, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
