const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Randomized Routing at Low Rates Makes Statistical Detection Query-Prohibitive'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Randomized Routing at Low Rates", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.45,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("Makes Statistical Detection Query-Prohibitive", {
    x: 0.4, y: 0.6, w: 9.2, h: 0.3,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Section 1: Two boxes with arrow
  const box1X = 0.6, box1Y = 1.3, boxW = 3.0, boxH = 0.9;

  // P_spec box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: box1X, y: box1Y, w: boxW, h: boxH,
    fill: { color: "FFFFFF" },
    line: { color: theme.primary, width: 2 },
    rectRadius: 0.03
  });
  slide.addText("P_spec(y|x)", {
    x: box1X, y: box1Y + 0.05, w: boxW, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });
  slide.addText("Specified Model", {
    x: box1X, y: box1Y + 0.45, w: boxW, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "center", valign: "middle"
  });

  // Arrow with probability label
  slide.addShape(pres.shapes.LINE, {
    x: 3.8, y: 1.75, w: 2.4, h: 0,
    line: { color: theme.accent, width: 2 }
  });
  // Arrowhead (triangle approximation)
  slide.addShape(pres.shapes.LINE, {
    x: 5.9, y: 1.65, w: 0.3, h: 0.2,
    line: { color: theme.accent, width: 2 }
  });
  slide.addShape(pres.shapes.LINE, {
    x: 5.9, y: 1.85, w: 0.3, h: -0.2,
    line: { color: theme.accent, width: 2 }
  });
  slide.addText("probability p", {
    x: 4.2, y: 1.4, w: 1.6, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.accent, bold: true, align: "center", valign: "middle"
  });

  // P_sub box
  const box2X = 6.3;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: box2X, y: box1Y, w: boxW, h: boxH,
    fill: { color: "FFFFFF" },
    line: { color: theme.secondary, width: 2 },
    rectRadius: 0.03
  });
  slide.addText("P_sub(y|x)", {
    x: box2X, y: box1Y + 0.05, w: boxW, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: true, align: "center", valign: "middle"
  });
  slide.addText("Substitute Model", {
    x: box2X, y: box1Y + 0.45, w: boxW, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "center", valign: "middle"
  });

  // Formula below boxes
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 2.5, w: 8.8, h: 0.5,
    fill: { color: theme.primary },
    rectRadius: 0.03
  });
  slide.addText("P_mixed = (1 - p) · P_spec + p · P_sub", {
    x: 0.6, y: 2.5, w: 8.8, h: 0.5,
    fontSize: 14, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Section 2: Three scenario cards
  const scenarios = [
    { p: "p = 0.5", desc: "50% substitute queries; detectable with moderate query budget", color: theme.accent },
    { p: "p = 0.1", desc: "10% substitute queries; requires 10x more queries for same detection power", color: theme.secondary },
    { p: "p → 0", desc: "Mixed distribution converges to P_spec; detection becomes exponentially harder", color: theme.primary }
  ];

  const sCardW = 2.8, sCardH = 0.85, sGap = 0.3, sStartX = 0.6;
  scenarios.forEach((sc, i) => {
    const sx = sStartX + i * (sCardW + sGap);
    const sy = 3.25;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: sy, w: sCardW, h: sCardH,
      fill: { color: "FFFFFF" },
      rectRadius: 0.03,
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
    });

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: sy, w: sCardW, h: 0.06,
      fill: { color: sc.color }
    });

    // p-value label
    slide.addText(sc.p, {
      x: sx + 0.15, y: sy + 0.1, w: sCardW - 0.3, h: 0.3,
      fontSize: 14, fontFace: "Calibri",
      color: sc.color, bold: true, align: "left", valign: "middle", margin: 0
    });

    // Description
    slide.addText(sc.desc, {
      x: sx + 0.15, y: sy + 0.4, w: sCardW - 0.3, h: 0.4,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "top", margin: 0
    });
  });

  // Section 3: Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.35, w: 9.2, h: 0.7,
    fill: { color: theme.accent },
    rectRadius: 0.03
  });
  slide.addText("As p → 0, the mixed distribution is indistinguishable from the specified model. Auditing requires O(1/p²) queries — becoming query-prohibitive for low substitution rates.", {
    x: 0.7, y: 4.35, w: 8.6, h: 0.7,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

