const slideConfig = {
  type: 'content',
  index: 7,
  title: 'Software-Only Auditing Methods Are Fundamentally Unreliable'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Software-Only Auditing Methods Are Fundamentally Unreliable", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.5,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0, fit: "shrink"
  });

  // Comparison matrix table
  const hdrOpts = { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 11, fontFace: "Calibri", align: "center", valign: "middle" };
  const cellW = { fill: { color: "FFFFFF" }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "left", valign: "middle" };
  const cellB = { fill: { color: theme.light }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "left", valign: "middle" };
  const hdrMethod = { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 11, fontFace: "Calibri", align: "left", valign: "middle" };
  const cellMethodW = { fill: { color: "FFFFFF" }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "left", valign: "middle", bold: true };
  const cellMethodB = { fill: { color: theme.light }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "left", valign: "middle", bold: true };

  const tableData = [
    [
      { text: "Method Type", options: hdrMethod },
      { text: "Core Weakness", options: hdrOpts },
      { text: "Practical Limitation", options: hdrOpts }
    ],
    [
      { text: "Text-Based Statistical Tests (e.g., MMD)", options: cellMethodW },
      { text: "Requires impractically large query budgets; fails against subtle substitutions", options: cellW },
      { text: "Cannot distinguish FP8 from original within error bars", options: cellW }
    ],
    [
      { text: "Log-Probability Methods", options: cellMethodB },
      { text: "Defeated by inference nondeterminism across software versions and hardware", options: cellB },
      { text: "Framework/hardware variation exceeds substitution signal", options: cellB }
    ],
    [
      { text: "Adversarial Countermeasures", options: cellMethodW },
      { text: "Benchmark evasion routes known prompts to genuine model; randomized routing dilutes signal", options: cellW },
      { text: "Detection cost grows as O(1/p²) — query-prohibitive at low p", options: cellW }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.4, y: 1.0, w: 9.2,
    colW: [2.2, 3.4, 3.6],
    border: { pt: 0.5, color: theme.light },
    rowH: [0.4, 0.75, 0.75, 0.75]
  });

  // Conclusion callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.9, w: 9.2, h: 0.6,
    fill: { color: theme.secondary },
    rectRadius: 0.03
  });
  slide.addText("No software-only method can provide reliable detection under realistic adversarial conditions.", {
    x: 0.7, y: 3.9, w: 8.6, h: 0.6,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "left", valign: "middle"
  });

  // Additional context bullets below
  slide.addText([
    { text: "Key insight: ", options: { bold: true, fontSize: 11, fontFace: "Calibri" } },
    { text: "Each method fails independently — combining them does not yield a reliable composite detector. The fundamental issue is that the space of legitimate model outputs is too large and too variable to distinguish from substitution artifacts.", options: { fontSize: 11, fontFace: "Calibri" } }
  ], {
    x: 0.4, y: 4.7, w: 9.2, h: 0.7,
    color: theme.secondary, align: "left", valign: "top"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

