const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 8,
  title: 'Trusted Execution Environments Provide Provable Cryptographic Model Integrity'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Trusted Execution Environments Provide Provable Cryptographic Model Integrity", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0, fit: "shrink"
  });

  // Left card: Software Methods
  const cardW = 4.3, cardH = 2.8;
  const leftX = 0.4, rightX = 5.3, cardY = 0.9;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: cardY, w: cardW, h: cardH,
    fill: { color: "FFFFFF" },
    rectRadius: 0.03,
    shadow: { type: "outer", blur: 5, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });
  // Top border bar - secondary (warning tone)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: cardY, w: cardW, h: 0.06,
    fill: { color: theme.secondary }
  });

  slide.addText("Software Methods", {
    x: leftX + 0.2, y: cardY + 0.15, w: cardW - 0.4, h: 0.35,
    fontSize: 16, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });

  // Software methods bullets with X markers
  const swBullets = [
    "Statistical tests: query-prohibitive",
    "Log-prob fingerprinting: defeated by nondeterminism",
    "Adversarial evasion: fundamentally unaddressable"
  ];

  swBullets.forEach((b, i) => {
    const by = cardY + 0.6 + i * 0.5;

    // Red-ish X indicator (using secondary color square)
    slide.addShape(pres.shapes.RECTANGLE, {
      x: leftX + 0.2, y: by + 0.07, w: 0.2, h: 0.2,
      fill: { color: theme.secondary }
    });
    slide.addText("X", {
      x: leftX + 0.2, y: by + 0.05, w: 0.2, h: 0.24,
      fontSize: 10, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    slide.addText(b, {
      x: leftX + 0.5, y: by, w: cardW - 0.7, h: 0.4,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // UNRELIABLE label
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX + 0.2, y: cardY + 2.15, w: 2.0, h: 0.35,
    fill: { color: theme.secondary },
    rectRadius: 0.02
  });
  slide.addText("UNRELIABLE", {
    x: leftX + 0.2, y: cardY + 2.15, w: 2.0, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Right card: TEE-Based Attestation
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: cardY, w: cardW, h: cardH,
    fill: { color: "FFFFFF" },
    rectRadius: 0.03,
    shadow: { type: "outer", blur: 5, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });
  // Top border bar - accent (trust tone)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: cardY, w: cardW, h: 0.06,
    fill: { color: theme.accent }
  });

  slide.addText("TEE-Based Attestation", {
    x: rightX + 0.2, y: cardY + 0.15, w: cardW - 0.4, h: 0.35,
    fontSize: 16, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });

  // TEE bullets with check markers
  const teeBullets = [
    "Provable: cryptographic attestation of model weights",
    "Efficient: modest performance overhead only",
    "Robust: immune to software-level evasion"
  ];

  teeBullets.forEach((b, i) => {
    const by = cardY + 0.6 + i * 0.5;

    // Green-ish check indicator
    slide.addShape(pres.shapes.RECTANGLE, {
      x: rightX + 0.2, y: by + 0.07, w: 0.2, h: 0.2,
      fill: { color: theme.accent }
    });
    slide.addText("✓", {
      x: rightX + 0.2, y: by + 0.05, w: 0.2, h: 0.24,
      fontSize: 11, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    slide.addText(b, {
      x: rightX + 0.5, y: by, w: cardW - 0.7, h: 0.4,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // PROVABLY SECURE label
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX + 0.2, y: cardY + 2.15, w: 2.8, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.02
  });
  slide.addText("PROVABLY SECURE", {
    x: rightX + 0.2, y: cardY + 2.15, w: 2.8, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Bottom banner
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.95, w: 9.2, h: 1.15,
    fill: { color: theme.primary },
    rectRadius: 0.03
  });

  slide.addText([
    { text: "NVIDIA Confidential Computing on H100 GPUs", options: { bold: true, fontSize: 13 } },
    { text: " provides practical TEE deployment today", options: { fontSize: 13 } },
    { text: "\n", options: { breakLine: true, fontSize: 6 } },
    { text: "Unlike ZKPs, TEEs are computationally feasible for models with billions of parameters", options: { fontSize: 12 } }
  ], {
    x: 0.7, y: 3.95, w: 8.6, h: 1.15,
    fontFace: "Calibri", color: "FFFFFF", align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

