const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 9,
  title: 'Key Takeaways: Close the Verification Gap with Hardware Attestation'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.4, y: 0.2, w: 9.2, h: 0.5,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("Close the Verification Gap with Hardware Attestation", {
    x: 0.4, y: 0.65, w: 9.2, h: 0.3,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // 5 takeaway items with numbered badges
  const takeaways = [
    "Model substitution is economically motivated and practically undetectable via software — providers save GPU costs while maintaining pricing",
    "FP8 quantization barely affects benchmark scores — performance drops fall within error bars on MMLU and GSM8K",
    "Inference nondeterminism across frameworks and hardware kills log-probability fingerprinting as a detection method",
    "Randomized substitution at low rates makes statistical detection query-prohibitive — requiring O(1/p²) queries",
    "Trusted Execution Environments are the only currently viable path to verifiable LLM APIs — provable, efficient, and deployable today"
  ];

  const itemStartY = 1.15, itemH = 0.6, itemGap = 0.05;

  takeaways.forEach((text, i) => {
    const iy = itemStartY + i * (itemH + itemGap);

    // Alternating subtle background strip
    if (i % 2 === 0) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.3, y: iy, w: 9.4, h: itemH,
        fill: { color: "FFFFFF", transparency: 50 }
      });
    }

    // Numbered circle badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.45, y: iy + 0.1, w: 0.4, h: 0.4,
      fill: { color: theme.accent }
    });
    slide.addText(String(i + 1), {
      x: 0.45, y: iy + 0.1, w: 0.4, h: 0.4,
      fontSize: 14, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    // Text
    slide.addText(text, {
      x: 1.0, y: iy, w: 8.5, h: itemH,
      fontSize: 12, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Bottom CTA banner
  const bannerY = 4.45;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: bannerY, w: 9.2, h: 0.6,
    fill: { color: theme.primary },
    rectRadius: 0.03
  });
  slide.addText("The community must adopt hardware-based attestation standards to ensure LLM API integrity.", {
    x: 0.7, y: bannerY, w: 8.6, h: 0.6,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Source
  slide.addText("arxiv.org/abs/2504.04715", {
    x: 0.4, y: 5.15, w: 3.0, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("9", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-09-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

