const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = 'Auditing Model Substitution in LLM APIs';
pres.author = 'arxiv.org/abs/2504.04715';

const theme = {
  primary: "03045e",
  secondary: "0077b6",
  accent: "00b4d8",
  light: "90e0ef",
  bg: "caf0f8"
};

for (let i = 1; i <= 9; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' }).then(() => {
  console.log('Presentation saved to output/final_deck.pptx');
}).catch(err => {
  console.error('Error:', err);
});

